import re, glob, json
meta={}
for path in sorted(glob.glob('reports/w*.md')):
    wid=path.split('/')[-1].replace('.md','').upper()
    lines=open(path).read().split('\n')
    head=lines[2:5]
    region=manager=year=None
    for ln in head:
        m=re.match(r'Region:\s*(\w+)',ln)
        if m: region=m.group(1)
        m=re.match(r'This site sits in the (\w+) region',ln)
        if m: region=m.group(1)
        m=re.match(r'A (\w+)-region site',ln)
        if m: region=m.group(1)
        m=re.match(r'(?:Site manager:|Managed by) (.+?)\.$',ln)
        if m: manager=m.group(1)
        m=re.match(r'(.+?) runs the floor here\.$',ln)
        if m: manager=m.group(1)
        m=re.search(r'(?:Opened in|Operating since|Commissioned) (\d{4})',ln)
        if m: year=int(m.group(1))
    assert region and manager and year, (wid,head)
    meta[wid]={'region':region.lower(),'manager':manager,'year':year}
stock=json.load(open('/tmp/stock.json'))
json.dump(meta,open('/tmp/meta.json','w'),indent=1)
print(json.dumps(meta,indent=0))
PY", "description": "Parse metadata from all reports"}

